import { Component, OnInit, ViewEncapsulation } from "@angular/core";
import { Router } from "@angular/router";


import { MenuController, Platform, ToastController } from "@ionic/angular";

import { SplashScreen } from "@ionic-native/splash-screen/ngx";
import { StatusBar } from "@ionic-native/status-bar/ngx";

import { Storage } from "@ionic/storage";

import { UserData } from "./providers/user-data";

@Component({
  selector: "app-root",
  templateUrl: "./app.component.html",
  styleUrls: ["./app.component.scss"],
  encapsulation: ViewEncapsulation.None,
})
export class AppComponent  {
  appPages = [
    {
      title: "Treatments",
      url: "/app/tabs/schedule",
      icon: "bar-chart",
    },
    {
      title: "Symptoms",
      url: "/app/tabs/symptoms",
      icon: "body",
    },
    {
      title: "Guidelines",
      url: "/app/tabs/guide",
      icon: "library",
    },

    {
      title: "About",
      url: "/app/tabs/about",
      icon: "information-circle",
    },
   
    {
      title: "Donate",
      url: "/app/tabs/donate",
      icon: "card",
    },
    {
      title: "Terms",
      url: "/app/tabs/terms",
      icon: "book",
    }
  ];
  loggedIn = false;
  dark = false;
  build: any = '1.2';

  constructor(
    private menu: MenuController,
    private platform: Platform,
    private router: Router,
    private splashScreen: SplashScreen,
    private statusBar: StatusBar,
    private storage: Storage,
    private userData: UserData,
    private toastCtrl: ToastController
  ) {
    this.initializeApp();
  }

 
  initializeApp() {
    this.platform.ready().then(() => {
      this.statusBar.styleDefault();
      this.splashScreen.hide();
      this.getBuild()
    
    });
  }

  async getBuild() {
   
    let _loadWizard = await this.storage.get("ion_did_wizard");
    let _build = await this.storage.get('build-ver');

    if(this.build !== _build) {
      this.storage.clear();
      this.storage.set('build-ver', this.build);
    
      if(_loadWizard == null) {
        this.storage.set('ion_did_wizard', false);
      }
    }
  }
  openTutorial() {
    this.menu.enable(false);
    this.storage.set('ion_did_tutorial', false);
    this.router.navigateByUrl('/tutorial');
  }




}
